"""Random arrays for the duplicate remover: a count line, then the values.

The array has to arrive sorted -- that is the precondition the in-place trick
relies on -- so every builder picks its distinct values first and only then
decides how many times each one repeats.
"""


def generate(rng, count):
    builders = (_scattered_repeats, _no_repeats, _one_long_run, _negatives)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n" % (len(values), " ".join(str(v) for v in values)),
        "description": description,
    }


def _expand(uniques, repeats):
    values = []
    for value, times in zip(uniques, repeats):
        values.extend([value] * times)
    return values


def _uniques(rng, how_many, low=0, high=40):
    return sorted(rng.sample(range(low, high), how_many))


def _scattered_repeats(rng, index):
    uniques = _uniques(rng, rng.randint(4, 7))
    repeats = [rng.randint(1, 3) for _ in uniques]
    return _case("repeats throughout #%d" % index, _expand(uniques, repeats))


def _no_repeats(rng, index):
    uniques = _uniques(rng, rng.randint(4, 8))
    return _case("nothing to remove #%d" % index, uniques,
                 "Already unique: the array comes back unchanged and the "
                 "count is the length it arrived with.")


def _one_long_run(rng, index):
    uniques = _uniques(rng, rng.randint(3, 5))
    repeats = [1] * len(uniques)
    repeats[rng.randrange(len(uniques))] = rng.randint(4, 7)
    return _case("one long run #%d" % index, _expand(uniques, repeats),
                 "A single value repeated several times in a row. The reading "
                 "index moves on; the writing index waits.")


def _negatives(rng, index):
    uniques = _uniques(rng, rng.randint(4, 6), -30, 15)
    repeats = [rng.randint(1, 3) for _ in uniques]
    return _case("negatives and zero #%d" % index, _expand(uniques, repeats))
